mapper.select:
SELECT usage_id, occurred_at, user_id, session_id, agent_id, agent_name, role, stage_key,
    run_id, model, provider, plane, prompt_tokens, completion_tokens, cached_tokens,
    total_tokens, latency_ms, success, error_type, reply_id
FROM llm_usage

    AND occurred_at >= #{from}
    AND occurred_at < #{to}
    AND model = #{model}
    AND plane = #{plane}
    AND (agent_id = #{agent} OR agent_name = #{agent})
    AND user_id = #{userId}

ORDER BY occurred_at DESC, usage_id DESC
LIMIT #{limit}
